scwin.checkVal = function() { return document.getElementsByClassName('pvtCheckContainer').length == 1; } scwin.unitTest = function() { //Unit WebSquare.wUnit.start(); WebSquare.wUnit.addCommand("pause", "500"); WebSquare.wUnit.addCommand("set", "document.getElementsByClassName('pvtTriangle')[1].click()"); WebSquare.wUnit.addCommand("pause", "400");
